class Command(BaseCommand):
    help = "Carrega classes e apropriações da planilha padrão de fluxo de desembolso."

    def handle(self, *args, **options):
        criadas_classes = 0
        criadas_apropriacoes = 0
        mapa = {}
        for codigo, nome in CLASSES:
            obj, criado = PlanoFinanceiro.objects.update_or_create(
                codigo=codigo,
                defaults={
                    "nome": nome,
                    "tipo": PlanoFinanceiro.Tipo.DESPESA,
                    "pai": None,
                    "ativo": True,
                },
            )
            mapa[nome] = obj
            criadas_classes += int(criado)

        for codigo, classe_nome, nome in APROPRIACOES:
            pai = mapa[classe_nome]
            _, criado = PlanoFinanceiro.objects.update_or_create(
                codigo=codigo,
                defaults={
                    "nome": nome,
                    "tipo": PlanoFinanceiro.Tipo.DESPESA,
                    "pai": pai,
                    "ativo": True,
                },
            )
            criadas_apropriacoes += int(criado)

        self.stdout.write(self.style.SUCCESS(
            f"Estrutura financeira carregada: {len(CLASSES)} classes e {len(APROPRIACOES)} apropriações. "
            f"Novas: {criadas_classes} classes e {criadas_apropriacoes} apropriações."
        ))
